const {chromium} = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const {spawn} = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const assert = require('node:assert/strict');
const root = path.resolve(__dirname, '../..');
const executable = path.resolve(process.argv[2] || path.join(root, 'dist', process.platform === 'win32' ? 's3-auditor.exe' : 's3-auditor'));
const temporary = fs.mkdtempSync(path.join(os.tmpdir(),'s3-browser-'));
const screenshots = process.argv[3] ? path.resolve(process.argv[3]) : temporary;
fs.mkdirSync(screenshots, {recursive:true});
const empty = path.join(temporary, 'empty-config'); fs.writeFileSync(empty,'');
const env = Object.fromEntries(Object.entries(process.env).filter(([k])=>! /^(AWS_|JIRA_|S3_AUDITOR_)/i.test(k)));
Object.assign(env,{AWS_CONFIG_FILE:empty,AWS_SHARED_CREDENTIALS_FILE:empty,AWS_EC2_METADATA_DISABLED:'true',AWS_ENDPOINT_URL:'http://127.0.0.1:1',AWS_MAX_ATTEMPTS:'1',S3_AUDITOR_DATA_DIR:path.join(temporary,'data'),S3_AUDITOR_NO_BROWSER:'1'});
let proc, browser, errors=[],external=0;
async function launch(){
 proc=spawn(executable,[],{env,stdio:['ignore','pipe','pipe'],windowsHide:true});
 return await new Promise((resolve,reject)=>{let output='';const timer=setTimeout(()=>reject(Error('launcher timeout')),15000);proc.on('error',reject);proc.stdout.on('data',data=>{output+=data.toString();const match=output.match(/http:\/\/\S+/);if(match){clearTimeout(timer);resolve(match[0]);}});});
}
async function stop(){if(proc&&!proc.killed){const stopped=new Promise(r=>proc.once('exit',r));proc.kill();await stopped;}const lock=path.join(temporary,'data','application.lock');if(fs.existsSync(lock))fs.unlinkSync(lock);}
(async()=>{
 try{
  let url=await launch();
  browser=await chromium.launch({executablePath:process.env.S3_AUDITOR_BROWSER || undefined,headless:true});
  console.log('Chromium version: '+browser.version());
  const context=await browser.newContext({viewport:{width:1280,height:900}});
  await context.route('**/*',route=>{if(!route.request().url().startsWith('http://127.0.0.1:')){external++;return route.abort();}return route.continue();});
  const page=await context.newPage();page.on('pageerror',()=>errors.push('page error'));page.on('console',msg=>{if(msg.type()==='error')errors.push('console error');});
  await page.goto(url);
  const theme=page.getByRole('button',{name:'Dark mode'});
  await theme.waitFor({state:'visible'});
  assert.equal(await page.evaluate(()=>getComputedStyle(document.body).backgroundColor),'rgb(255, 255, 255)');
  await page.screenshot({path:path.join(screenshots,'welcome-light.png'),fullPage:true});
  await theme.click();assert.equal(await theme.getAttribute('aria-pressed'),'true');
  assert.equal(await page.evaluate(()=>getComputedStyle(document.body).backgroundColor),'rgb(0, 0, 0)');
  await page.getByRole('link',{name:'Set up my workspace'}).click();
  assert.equal(await theme.getAttribute('aria-pressed'),'true');
  await page.getByRole('button',{name:'Check AWS identity without scanning'}).focus();
  assert.notEqual(await page.locator(':focus').evaluate(el=>getComputedStyle(el).outlineStyle),'none');
  await page.screenshot({path:path.join(screenshots,'setup-dark.png'),fullPage:true});
  await page.goto(url);await page.getByRole('button',{name:'Try the guided demo'}).click();
  await page.locator('#results').waitFor();
  assert.equal(await page.locator('#results tbody tr').count(),4);
  assert.equal(await page.getByRole('heading',{name:'Jira handoff'}).count(),0);
  assert.equal(await page.evaluate(()=>getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()),'#087e83');
  await page.screenshot({path:path.join(screenshots,'results-dark.png'),fullPage:true});
  await theme.click();
  assert.equal(await page.evaluate(()=>getComputedStyle(document.documentElement).getPropertyValue('--accent').trim()),'#087e83');
  await page.screenshot({path:path.join(screenshots,'results-light.png'),fullPage:true});
  const downloadPromise=page.waitForEvent('download');await page.getByRole('link',{name:'Download JSON evidence'}).click();
  const downloaded=await downloadPromise;const exported=JSON.parse(fs.readFileSync(await downloaded.path(),'utf8'));assert.equal(exported.Demo,true);assert.equal(exported.Reports.length,4);
  await page.setViewportSize({width:390,height:844});
  assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'page overflow on mobile');
  await theme.click();await page.screenshot({path:path.join(screenshots,'results-mobile-dark.png'),fullPage:true});
  await page.reload();assert.equal(await theme.getAttribute('aria-pressed'),'true');
  await stop();url=await launch();await page.goto(url);
  assert.equal(await theme.getAttribute('aria-pressed'),'true');assert.equal(await page.locator('#results tbody tr').count(),4);
  const noJS=await browser.newContext({javaScriptEnabled:false});const fallback=await noJS.newPage();await fallback.goto(url);assert.equal(await fallback.locator('#results tbody tr').count(),4);assert.equal(await fallback.getByRole('button',{name:'Dark mode'}).count(),0);await noJS.close();
  await page.setViewportSize({width:1280,height:900});
  await page.getByRole('button',{name:'Try the verification walkthrough'}).click();
  await page.locator('#verification').waitFor();
  const bucketDetail=page.locator('#verification > details');
  await bucketDetail.locator(':scope > summary').click();
  assert.equal(await page.locator('#results tbody tr').count(),1);
  assert((await bucketDetail.innerText()).includes('disabled → enabled'));
  await page.screenshot({path:path.join(screenshots,'verification-dark.png'),fullPage:true});
  let verificationDownload=page.waitForEvent('download');await page.getByRole('link',{name:'Download verification record'}).click();
  let record=JSON.parse(fs.readFileSync(await (await verificationDownload).path(),'utf8'));
  assert.equal(record.Buckets[0].OpenConcerns,0);
  assert.deepEqual(record.Buckets[0].Controls[0].Timeline.map(x=>x.State),['concern','unknown','not_assessed','clear']);
  await page.getByRole('link',{name:/2 - Inspection denied/}).click();
  verificationDownload=page.waitForEvent('download');await page.getByRole('link',{name:'Download verification record'}).click();
  record=JSON.parse(fs.readFileSync(await (await verificationDownload).path(),'utf8'));
  assert.equal(record.Buckets[0].OpenConcerns,2);assert.equal(record.Buckets[0].Controls[0].Episodes[0].VerifiedClear,null);
  await page.getByRole('link',{name:/3 - Bucket not assessed/}).click();
  assert.equal(await page.locator('#results tbody tr').count(),0);
  assert((await page.locator('#verification').innerText()).includes('Not assessed in this scan'));
  await page.getByRole('link',{name:/4 - Controls verified clear/}).click();
  await bucketDetail.locator(':scope > summary').click();
  await theme.click();await page.screenshot({path:path.join(screenshots,'verification-light.png'),fullPage:true});
  await page.setViewportSize({width:390,height:844});
  assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'verification page overflow on mobile');
  assert(await page.locator('#verification .scroll').evaluate(el=>el.scrollWidth>el.clientWidth),'mobile table must scroll instead of crushing columns');
  await page.screenshot({path:path.join(screenshots,'verification-mobile.png'),fullPage:true});
  assert.equal(errors.length,0,'JavaScript or CSP errors');assert.equal(external,0,'unexpected external request');
  console.log('PASS: real headless Chromium light/dark, matching accent, setup navigation, keyboard focus, demo, download, mobile overflow, reload/restart theme persistence, no-JS fallback, four-stage verification and historical record downloads; no external requests or console errors.');
 } finally {if(browser)await browser.close();await stop();fs.rmSync(temporary,{recursive:true,force:true});}
})().catch(()=>{console.error('Browser checks failed; inspect the local check assertions. No launcher URL recorded.');process.exitCode=1;});
